def transform(grid):
    h, w = len(grid), len(grid[0])

    # Read the ordered colors from a nonzero sequence repeated on three
    # consecutive identical rows.
    sequences = []
    for r in range(h - 2):
        if grid[r] == grid[r + 1] == grid[r + 2]:
            vals = [v for v in grid[r] if v != 0]
            if vals:
                sequences.append(vals)

    # Also allow the repeated color key to be oriented vertically.
    for c in range(w):
        col0 = [grid[r][c] for r in range(h)]
        for r in range(h - 2):
            if col0[r] != 0 and col0[r] == col0[r + 1] == col0[r + 2]:
                vals = []
                rr = r
                while rr < h and grid[rr][c] == col0[r]:
                    vals.append(grid[rr][c])
                    rr += 1
                # Vertical keys are handled as a repeated column pattern;
                # collect colors across neighboring columns instead below.
        for c0 in range(w - 2):
            if all(grid[r][c0] == grid[r][c0 + 1] == grid[r][c0 + 2]
                   for r in range(h)):
                pass

    # In these tasks the key is a nonzero run in a row repeated three times.
    colors = max(sequences, key=len)

    # Find the largest connected component whose color occurs in the key.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color not in colors or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((len(comp), color, comp))

    _, source_color, shape = max(components)
    top = min(y for y, x in shape)
    bottom = max(y for y, x in shape)
    height = bottom - top + 1
    source_index = colors.index(source_color)

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        shift = (i - source_index) * height
        for y, x in shape:
            ny = y + shift
            if 0 <= ny < h:
                out[ny][x] = color
    return out
